svg.script:
const snapshots = {
  A: {
    "_config/launch.json": "launch-v1",
    "donner/skript.pdf": "skript-v1",
    "README.md": "readme-v1"
  },
  B: {
    "_config/launch.json": "launch-v1",
    "donner/00_ascii_tabelle/00_ascii_tabelle.ino": "ascii-v1",
    "README.md": "readme-v1"
  },
  C: {
    "_config/launch.json": "launch-v1",
    "donner/00_ascii_tabelle/00_ascii_tabelle.ino": "ascii-v2",
    "donner/01_joystick/01_joystick.ino": "joystick-v1",
    "README.md": "readme-v1"
  },
  D: {
    "_config/launch.json": "launch-v1",
    "donner/skript.pdf": "skript-v1",
    "wurzelsepp/mitschrift.md": "mitschrift-v1",
    "README.md": "readme-v1"
  },
  E: {
    "_config/launch.json": "launch-v1",
    "donner/skript.pdf": "skript-v1",
    "donner/00_ascii_tabelle/00_ascii_tabelle.ino": "ascii-v1",
    "wurzelsepp/mitschrift.md": "mitschrift-v1",
    "README.md": "readme-v1"
  }
};

const parentOf = {
  A: null,
  B: "A",
  C: "B",
  D: "A",
  E: "D"
};

let primary = "A";
let secondary = null;

const NS = "http://www.w3.org/2000/svg";
const panelContent = document.getElementById("panelContent");
const panelTitle = document.getElementById("panelTitle");
const panelSubtitle = document.getElementById("panelSubtitle");

function make(name, attrs = {}, text = null) {
  const n = document.createElementNS(NS, name);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
  if (text !== null) n.textContent = text;
  return n;
}

function clearPanel() {
  while (panelContent.firstChild) panelContent.removeChild(panelContent.firstChild);
}

function updateCommitClasses() {
  document.querySelectorAll(".commit").forEach(g => {
    g.classList.remove("primary", "secondary");
    const id = g.getAttribute("data-commit");
    if (id === primary) g.classList.add("primary");
    if (id === secondary) g.classList.add("secondary");
  });
}

function buildTree(paths) {
  const root = {};
  for (const path of paths) {
    const parts = path.split("/");
    let node = root;
    parts.forEach((part, i) => {
      if (i === parts.length - 1) node[part] = null;
      else {
        if (!node[part]) node[part] = {};
        node = node[part];
      }
    });
  }
  return root;
}

function flattenTree(tree, depth = 0, prefix = "", lines = []) {
  const entries = Object.entries(tree);
  entries.sort(([a,av],[b,bv]) => {
    const ad = av !== null, bd = bv !== null;
    if (ad !== bd) return ad ? -1 : 1;
    return a.localeCompare(b);
  });
  for (const [name, value] of entries) {
    const fullPath = prefix ? `${prefix}/${name}` : name;
    lines.push({ name, depth, folder: value !== null, path: fullPath });
    if (value !== null) flattenTree(value, depth + 1, fullPath, lines);
  }
  return lines;
}

function parentDiffStatuses(commit) {
  const parent = parentOf[commit];
  const current = snapshots[commit];
  if (!parent) return {};
  const previous = snapshots[parent];
  const status = {};
  for (const [path, value] of Object.entries(current)) {
    if (!(path in previous)) status[path] = "A";
    else if (previous[path] !== value) status[path] = "M";
  }
  return status;
}

function renderSnapshot(commit) {
  clearPanel();
  panelTitle.textContent = `Snapshot ${commit}`;
  const parent = parentOf[commit];
  if (parent) {
    panelSubtitle.textContent = `Dateistand dieses Commits · Vergleich zu Parent ${parent}`;
  } else {
    panelSubtitle.textContent = "Dateistand dieses Commits · Wurzelcommit";
  }

  const statuses = parentDiffStatuses(commit);
  const lines = flattenTree(buildTree(Object.keys(snapshots[commit])));

  let y = 0;
  for (const line of lines) {
    const prefix = line.folder ? "▾ " : "• ";
    let cls = line.folder ? "tree-folder mono" : "tree-file mono";
    if (!line.folder && statuses[line.path] === "A") cls = "tree-file-added mono";
    if (!line.folder && statuses[line.path] === "M") cls = "tree-file-modified mono";

    panelContent.appendChild(make("text", {
      x: 22 * line.depth,
      y: y,
      class: cls,
      "font-size": "17"
    }, prefix + line.name));

    if (!line.folder && statuses[line.path] === "A") {
      panelContent.appendChild(make("text", {
        x: 420, y: y, class: "status-added mono", "font-size":"14"
      }, "neu"));
    }
    if (!line.folder && statuses[line.path] === "M") {
      panelContent.appendChild(make("text", {
        x: 420, y: y, class: "status-modified mono", "font-size":"14"
      }, "geändert"));
    }

    y += 30;
  }
}

function computeDiff(a, b) {
  const A = snapshots[a], B = snapshots[b];
  const all = [...new Set([...Object.keys(A), ...Object.keys(B)])].sort();
  const rows = [];
  for (const path of all) {
    if (!(path in A)) rows.push({ status: "A", path });
    else if (!(path in B)) rows.push({ status: "D", path });
    else if (A[path] !== B[path]) rows.push({ status: "M", path });
  }
  return rows;
}

function renderDiff(a, b) {
  clearPanel();
  panelTitle.textContent = `Diff ${a} → ${b}`;
  panelSubtitle.textContent = "Unterschiede auf Dateiebene";

  const legend = [
    ["A", "neu", "status-added"],
    ["M", "geändert", "status-modified"],
    ["D", "gelöscht", "status-deleted"]
  ];
  let lx = 0;
  for (const [code, label, cls] of legend) {
    panelContent.appendChild(make("text", {x: lx, y: 0, class: `${cls} mono`, "font-size":"15"}, code));
    panelContent.appendChild(make("text", {x: lx + 20, y: 0, class: "small"}, label));
    lx += 120;
  }

  const diff = computeDiff(a, b);
  let y = 45;
  if (diff.length === 0) {
    panelContent.appendChild(make("text", {x:0, y:y, class:"label"}, "Keine Dateiunterschiede."));
    return;
  }
  for (const row of diff) {
    const cls = row.status === "A" ? "status-added" :
                row.status === "M" ? "status-modified" : "status-deleted";
    panelContent.appendChild(make("text", {
      x: 0, y: y, class: `${cls} mono`, "font-size":"17"
    }, row.status));
    panelContent.appendChild(make("text", {
      x: 34, y: y, class: "tree-file mono", "font-size":"16"
    }, row.path));
    y += 31;
  }
}

function render() {
  updateCommitClasses();
  if (secondary) renderDiff(primary, secondary);
  else renderSnapshot(primary);
}

document.querySelectorAll(".commit").forEach(g => {
  g.addEventListener("click", evt => {
    const commit = g.getAttribute("data-commit");
    if (evt.shiftKey) {
      if (commit === primary) secondary = null;
      else secondary = commit;
    } else {
      primary = commit;
      secondary = null;
    }
    render();
  });
});

render();
